// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MY_BANK c;

    function setUp() public {
        c = new MY_BANK(address(new Log()));
    }

    function testFuzz_property(uint256 putAmount, uint256 collectAmount, uint256 unlockTime) public {
        vm.assume(putAmount <= VALUE_CAP);
        putAmount = bound(putAmount, 1 ether, 100 ether);
        collectAmount = bound(collectAmount, 1 ether, putAmount);
        unlockTime = bound(unlockTime, 0, block.timestamp + 1000);

        address actor = address(0xA11CE);
        vm.deal(actor, putAmount);

        vm.prank(actor);
        c.Put{value: putAmount}(unlockTime);

        vm.warp(block.timestamp + 1001);

        vm.prank(actor);
        bool ok1; try c.Collect(collectAmount) { ok1 = true; } catch { ok1 = false; }

        vm.prank(actor);
        bool ok2; try c.Collect{value: 0}(collectAmount) { ok2 = true; } catch { ok2 = false; }

        assertTrue(ok1 && ok2, "second Collect must not revert due to permanent lock");
    }
}
